; ST/STE 68000 / 512 KiB / PAL. YM2149 on ST, native DMA on STE for STV1.
; Original implementation. Input VIDEO.STV, generated by tools/encode.py.
        section text
start:
        move.l  4(sp),a5
        lea     stack_end,sp
        move.l  #program_end,d0
        sub.l   a5,d0
        move.l  d0,-(sp)
        move.l  a5,-(sp)
        clr.w   -(sp)
        move.w  #$4a,-(sp)
        trap    #1
        lea     12(sp),sp
        tst.l   d0
        bmi     fail
        move.w  #4,-(sp)
        trap    #14
        addq.l  #2,sp
        cmp.w   #2,d0
        beq     fail
        move.w  d0,old_rez
        move.w  #2,-(sp)
        trap    #14
        addq.l  #2,sp
        move.l  d0,old_screen
        pea     detect_ste
        move.w  #38,-(sp)
        trap    #14
        addq.l  #6,sp
        move.w  d0,machine_ste
        lea     default_name,a0
        lea     filename,a1
copy_default:
        move.b  (a0)+,(a1)+
        bne.s   copy_default
play_file:
        lea     play_state_start,a0
clear_play_state:
        clr.b   (a0)+
        cmpa.l  #play_state_end,a0
        blo.s   clear_play_state
        clr.w   -(sp)
        pea     filename
        move.w  #$3d,-(sp)
        trap    #1
        addq.l  #8,sp
        tst.l   d0
        bmi     select_file
        move.w  d0,handle
        lea     header,a0
        bsr     read_block
        cmp.l   #32768,d0
        bne     close_fail
        cmp.l   #$53544656,header
        bne     close_fail
        move.w  #12,audio_stride
        cmp.l   #$49443100,header+4
        beq.s   format_ok
        cmp.l   #$49443200,header+4
        beq.s   single_write_format
        cmp.l   #$49443300,header+4
        bne     close_fail
        move.w  #1,audio_continuous
        move.w  #12800,timer_period
single_write_format:
        move.w  #1,audio_stream_mode
        move.w  #4,audio_stride
format_ok:
        tst.w   audio_stream_mode
        bne.s   output_mode_ready
        move.w  machine_ste,audio_dma_active
output_mode_ready:
        move.w  #50,timer_divisor
        move.w  #2,frame_ticks
        cmp.l   #25,header+16
        beq.s   check_rate
        cmp.l   #1250,header+16
        bne     close_fail
        move.w  #75,timer_divisor
        move.w  #19200,timer_period
        move.w  #4,frame_ticks
        cmp.l   #8192,header+12
        bne     close_fail
        bra.s   header_ok
check_rate:
        cmp.l   #12288,header+12
        bne     close_fail
header_ok:
        move.l  header+8,remaining
        beq     close_fail
        lea     header+256,a0
        lea     ym_lut,a1
        move.w  #767,d0
copy_lut:
        move.l  (a0)+,(a1)+
        dbra    d0,copy_lut
        lea     buffers+255,a0
        move.l  a0,d0
        and.l   #$ffffff00,d0
        move.l  d0,load_ptr
        move.l  d0,first_ptr
        move.l  #audio_buffers,load_audio
        bsr     load_frame
        tst.w   io_error
        bne     close_fail
        ; TOS Setscreen clears the new logical screen: preserve the first image.
        move.l  first_ptr,a0
        lea     header,a1
        move.w  #7999,d0
save_first:
        move.l  (a0)+,(a1)+
        dbra    d0,save_first
        clr.w   -(sp)
        move.l  first_ptr,-(sp)
        move.l  first_ptr,-(sp)
        move.w  #5,-(sp)
        trap    #14
        lea     12(sp),sp
        lea     header,a0
        move.l  first_ptr,a1
        move.w  #7999,d0
restore_first:
        move.l  (a0)+,(a1)+
        dbra    d0,restore_first
        clr.l   -(sp)
        move.w  #32,-(sp)
        trap    #1
        addq.l  #6,sp
        move.l  d0,old_ssp
        move.w  sr,old_sr
        move.w  #$2700,sr
        move.l  $70.w,old_vbl
        move.l  $134.w,old_timera
        movem.l $ffff8240.w,d0-d7
        movem.l d0-d7,old_palette
        lea     old_mfp,a0
        move.b  $fffffa07.w,(a0)+
        move.b  $fffffa13.w,(a0)+
        move.b  $fffffa17.w,(a0)+
        move.b  $fffffa19.w,(a0)+
        move.b  $fffffa1f.w,(a0)+
        lea     old_ym,a0
        moveq   #7,d0
        moveq   #3,d1
save_ym:
        move.b  d0,$ffff8800.w
        move.b  $ffff8800.w,(a0)+
        addq.b  #1,d0
        dbra    d1,save_ym
        move.b  old_ym,d0
        or.b    #$3f,d0
        move.b  #7,$ffff8800.w
        move.b  d0,$ffff8802.w
        move.l  #$08000000,$ffff8800.w
        move.l  #$09000000,$ffff8800.w
        move.l  #$0a000000,$ffff8800.w
        tst.w   audio_dma_active
        beq.s   setup_timer
        bsr     dma_save
setup_timer:
        clr.b   $fffffa19.w
        bclr    #5,$fffffa0b.w
        bclr    #5,$fffffa0f.w
        move.l  #timer_a,$134.w
        tst.w   audio_stream_mode
        beq.s   audio_handler_ready
        move.l  #timer_a_single,$134.w
audio_handler_ready:
        tst.w   audio_continuous
        beq.s   flow_handler_ready
        move.l  #timer_a_flow,$134.w
flow_handler_ready:
        move.l  #vbl,$70.w
        tst.w   audio_dma_active
        bne.s   audio_setup_done
        bset    #5,$fffffa07.w
        bset    #5,$fffffa13.w
        move.b  timer_divisor+1,$fffffa1f.w
        move.b  #1,$fffffa19.w
audio_setup_done:
        move.l  first_ptr,pending
        move.l  #audio_buffers,pending_audio
        move.w  #1,pending_valid
        move.w  frame_ticks,ticks
        move.w  #$2300,sr
        move.l  first_ptr,d0
        add.l   #32768,d0
        move.l  d0,load_ptr
        move.l  #audio_buffers+8192,load_audio
stream:
        tst.l   remaining
        beq     drain
        bsr     load_frame
        tst.w   io_error
        bne     drain
wait_queue:
        tst.w   ready
        beq.s   queue
        stop    #$2300
        bsr     check_controls
        tst.w   abort
        bne     restore
        bra.s   wait_queue
queue:
        move.l  load_ptr,queued
        move.l  load_audio,queued_audio
        move.w  #1,ready
        move.l  load_ptr,d0
        add.l   #32768,d0
        move.l  first_ptr,d1
        add.l   #98304,d1
        cmp.l   d1,d0
        blo.s   next_load
        move.l  first_ptr,d0
next_load:
        move.l  d0,load_ptr
        add.l   #8192,load_audio
        cmp.l   #audio_buffers+24576,load_audio
        blo.s   wait_consumed
        move.l  #audio_buffers,load_audio
        ; Do not reuse the queued buffer until the VBL has consumed it.
wait_consumed:
        tst.w   ready
        beq     stream
        stop    #$2300
        bsr     check_controls
        tst.w   abort
        bne.s   restore
        bra.s   wait_consumed
drain:
        move.l  vbl_count,d0
        moveq   #0,d1
        move.w  frame_ticks,d1
        add.l   d1,d1
        add.l   d1,d0
wait_end:
        stop    #$2300
        bsr     check_controls
        tst.w   abort
        bne.s   restore
        cmp.l   vbl_count,d0
        bhi.s   wait_end
restore:
        move.w  #$2700,sr
        clr.b   $fffffa19.w
        tst.w   audio_dma_active
        beq.s   restore_timer
        bsr     dma_restore
restore_timer:
        bclr    #5,$fffffa0b.w
        bclr    #5,$fffffa0f.w
        bsr     count_audio
        bsr     count_flow
        move.l  old_vbl,$70.w
        move.l  old_timera,$134.w
        lea     old_mfp,a0
        move.b  (a0)+,$fffffa07.w
        move.b  (a0)+,$fffffa13.w
        move.b  (a0)+,$fffffa17.w
        move.b  (a0)+,d0
        move.b  (a0)+,$fffffa1f.w
        move.b  d0,$fffffa19.w
        lea     old_ym,a0
        moveq   #7,d0
        moveq   #3,d1
restore_ym:
        move.b  d0,$ffff8800.w
        move.b  (a0)+,$ffff8802.w
        addq.b  #1,d0
        dbra    d1,restore_ym
        movem.l old_palette,d0-d7
        movem.l d0-d7,$ffff8240.w
        move.w  old_sr,sr
        move.l  old_ssp,-(sp)
        move.w  #32,-(sp)
        trap    #1
        addq.l  #6,sp
        move.w  old_rez,-(sp)
        move.l  old_screen,-(sp)
        move.l  old_screen,-(sp)
        move.w  #5,-(sp)
        trap    #14
        lea     12(sp),sp
        move.w  handle,-(sp)
        move.w  #$3e,-(sp)
        trap    #1
        addq.l  #4,sp
        ; Persist actual counters after restoring all interrupt handlers.
        clr.w   -(sp)
        pea     stats_name
        move.w  #$3c,-(sp)
        trap    #1
        addq.l  #8,sp
        tst.l   d0
        bmi     playback_finished
        move.w  d0,handle
        pea     stats
        move.l  #24,-(sp)
        move.w  handle,-(sp)
        move.w  #$40,-(sp)
        trap    #1
        lea     12(sp),sp
        move.w  handle,-(sp)
        move.w  #$3e,-(sp)
        trap    #1
        addq.l  #4,sp
playback_finished:
        cmp.w   #2,abort
        beq     select_file
exit:
        tst.w   aes_active
        beq.s   exit_tos
        lea     aes_exit_control,a0
        bsr     aes_call
exit_tos:
        clr.w   -(sp)
        trap    #1
close_fail:
        move.w  handle,-(sp)
        move.w  #$3e,-(sp)
        trap    #1
        addq.l  #4,sp
fail:
        pea     error_msg
        move.w  #9,-(sp)
        trap    #1
        addq.l  #6,sp
        move.w  #7,-(sp)
        trap    #1
        addq.l  #2,sp
        bra.s   exit
; Read the BIOS keyboard state in the main loop, outside interrupt context.
; TOS owns IKBD keyboard interrupts and updates Kbshift even when a make code
; has already been consumed before our VBL polling sees it.
check_controls:
        movem.l d0-d2/a0-a2,-(sp)
        ifd TEST_SELECTOR
        tst.w   test_shift_once
        bne.s   test_shift_done
        cmp.l   #30,frames_shown
        blo.s   test_shift_done
        move.w  #1,test_shift_once
        move.w  #1,-(sp)
        move.w  #11,-(sp)
        trap    #13
        addq.l  #4,sp
test_shift_done:
        endc
        move.w  #-1,-(sp)
        move.w  #11,-(sp)
        trap    #13
        addq.l  #4,sp
        btst    #0,d0
        beq.s   check_escape
        move.w  #2,abort
        bra.s   controls_done
check_escape:
        move.w  #2,-(sp)
        move.w  #1,-(sp)
        trap    #13
        addq.l  #4,sp
        tst.l   d0
        beq.s   controls_done
        move.w  #2,-(sp)
        move.w  #2,-(sp)
        trap    #13
        addq.l  #4,sp
        swap    d0
        cmp.b   #1,d0
        bne.s   controls_done
        move.w  #1,abort
controls_done:
        movem.l (sp)+,d0-d2/a0-a2
        rts
; AES is initialized only after playback restores TOS and returns to user mode.
select_file:
        ifd TEST_SELECTOR
        clr.w   -(sp)
        move.w  #11,-(sp)
        trap    #13
        addq.l  #4,sp
        endc
        tst.w   aes_active
        bne.s   selector_path
        lea     aes_init_control,a0
        bsr     aes_call
        tst.w   aes_intout
        bmi     exit
        move.w  #1,aes_active
selector_path:
        tst.b   selector_mask
        bne.s   show_selector
        move.w  #$19,-(sp)
        trap    #1
        addq.l  #2,sp
        add.b   #'A',d0
        move.b  d0,selector_mask
        move.b  #':',selector_mask+1
        clr.w   -(sp)
        pea     selector_mask+2
        move.w  #$47,-(sp)
        trap    #1
        addq.l  #8,sp
        lea     selector_mask+2,a0
find_mask_end:
        tst.b   (a0)+
        bne.s   find_mask_end
        subq.l  #1,a0
        cmp.b   #'\',-1(a0)
        beq.s   append_mask
        move.b  #'\',(a0)+
append_mask:
        lea     mask_suffix,a1
copy_mask:
        move.b  (a1)+,(a0)+
        bne.s   copy_mask
show_selector:
        move.l  #selector_mask,aes_addrin
        move.l  #selector_name,aes_addrin+4
        lea     aes_fsel_control,a0
        bsr     aes_call
        tst.w   aes_intout
        beq     exit
        tst.w   aes_intout+2
        beq     exit
        tst.b   selector_name
        beq.s   show_selector
        lea     selector_mask,a0
        lea     filename,a1
        move.l  a1,a2
copy_directory:
        move.b  (a0)+,d0
        beq.s   append_filename
        move.b  d0,(a1)+
        cmp.b   #'\',d0
        bne.s   copy_directory
        move.l  a1,a2
        bra.s   copy_directory
append_filename:
        move.l  a2,a1
        lea     selector_name,a0
copy_selection:
        move.b  (a0)+,(a1)+
        bne.s   copy_selection
        bra     play_file
aes_call:
        move.l  a0,aes_pb
        move.l  #aes_pb,d1
        move.w  #200,d0
        trap    #2
        rts
load_frame:
        move.l  load_ptr,a0
        bsr     read_block
        cmp.l   #32768,d0
        beq.s   read_ok
        move.w  #1,io_error
read_ok:
        tst.w   io_error
        bne     no_expand
        move.l  load_ptr,a0
        move.w  32760(a0),d2
        beq.s   invalid_audio
        cmp.w   #656,d2
        bhi.s   invalid_audio
        move.l  load_audio,a1
        tst.w   audio_dma_active
        bne     expand_dma
        move.w  d2,8188(a1)
        lea     32032(a0),a0
        lea     ym_lut,a2
        subq.w  #1,d2
        tst.w   audio_stream_mode
        bne.s   expand_single
expand_audio:
        moveq   #0,d0
        move.b  (a0)+,d0
        move.w  d0,d1
        add.w   d0,d0
        add.w   d1,d0
        lsl.w   #2,d0
        lea     (a2,d0.w),a3
        move.l  (a3)+,(a1)+
        move.l  (a3)+,(a1)+
        move.l  (a3)+,(a1)+
        dbra    d2,expand_audio
        bra     no_expand
expand_single:
        moveq   #0,d0
        move.b  (a0)+,d0
        cmp.b   #48,d0
        bhs.s   invalid_audio
        move.w  d0,d1
        add.w   d0,d0
        add.w   d1,d0
        lsl.w   #2,d0
        move.l  (a2,d0.w),(a1)+
        dbra    d2,expand_single
        bra     no_expand
invalid_audio:
        move.w  #1,io_error
        bra     no_expand
; Native STE DAC. Resample the unsigned PCM to 12517 Hz with linear
; interpolation. Main-thread work only; no per-sample MFP/YM interrupts.
expand_dma:
        move.w  #500,d6
        move.w  #17,d0
        cmp.w   #4,frame_ticks
        bne.s   dma_length
        move.w  #1000,d6
        moveq   #34,d0
dma_length:
        add.w   d0,dma_fraction
        cmp.w   #50,dma_fraction
        blo.s   dma_length_ready
        sub.w   #50,dma_fraction
        addq.w  #2,d6
dma_length_ready:
        move.w  d6,8188(a1)
        lea     32032(a0),a0
        moveq   #0,d5
        move.w  d2,d5
        subq.w  #1,d5
        swap    d5
        move.w  d6,d4
        subq.w  #1,d4
        divu    d4,d5
        and.l   #$ffff,d5
        moveq   #0,d3
        move.w  d6,d7
        subq.w  #1,d7
dma_resample:
        move.l  d3,d0
        swap    d0
        moveq   #0,d1
        move.b  (a0,d0.w),d1
        moveq   #0,d4
        move.b  1(a0,d0.w),d4
        sub.w   d1,d4
        move.w  d3,d0
        lsr.w   #1,d0
        muls    d0,d4
        asr.l   #8,d4
        asr.l   #7,d4
        add.w   d4,d1
        eor.b   #$80,d1
        move.b  d1,(a1)+
        add.l   d5,d3
        dbra    d7,dma_resample
no_expand:
        subq.l  #1,remaining
        rts
read_block:
        move.l  a0,-(sp)
        move.l  #32768,-(sp)
        move.w  handle,-(sp)
        move.w  #$3f,-(sp)
        trap    #1
        lea     12(sp),sp
        rts
vbl:
        movem.l d0-d7/a0,-(sp)
        addq.l  #1,$466.w
        addq.l  #1,vbl_count
        tst.w   pending_valid
        beq     no_latch
        move.l  pending,a0
        movem.l 32000(a0),d0-d7
        movem.l d0-d7,$ffff8240.w
        move.w  #$2700,sr
        bsr     count_audio
        tst.w   audio_dma_active
        beq.s   latch_ym
        move.l  pending_audio,a0
        moveq   #0,d0
        move.w  8188(a0),d0
        add.l   d0,samples_played
        tst.w   dma_started
        bne.s   dma_latch_done
        bsr     dma_set_next
        move.b  #3,$ffff8901.w
        move.w  #1,dma_started
dma_latch_done:
        move.w  #$2400,sr
        bra     latch_complete
latch_ym:
        tst.w   audio_continuous
        beq.s   latch_ym_reset
        tst.w   audio_started
        bne     flow_phase
        move.w  #1,audio_started
latch_ym_reset:
        tst.w   audio_stream_mode
        beq.s   audio_frame_ready
        move.l  32744(a0),$ffff8800.w
        move.l  32748(a0),$ffff8800.w
        move.l  32752(a0),$ffff8800.w
audio_frame_ready:
        move.l  pending_audio,a0
        move.l  a0,audio_cursor
        move.l  a0,audio_start
        moveq   #0,d0
        move.w  8188(a0),d0
        mulu    audio_stride,d0
        add.l   a0,d0
        move.l  d0,audio_end
        move.w  #$2400,sr
        bra.s   latch_complete
; Keep every command. Small clock corrections keep the continuous audio
; within a few samples of the video, instead of dropping a tail each frame.
flow_phase:
        moveq   #0,d0
        move.w  timer_divisor,d0
        lsl.l   #8,d0
        move.l  audio_start,d1
        cmp.l   pending_audio,d1
        bne.s   flow_behind
        move.l  audio_cursor,d1
        sub.l   audio_start,d1
        add.l   d1,d0
        bra.s   flow_rate
flow_behind:
        tst.l   d1
        beq.s   flow_rate
        move.l  audio_end,d1
        sub.l   audio_cursor,d1
        sub.l   d1,d0
flow_rate:
        moveq   #0,d1
        move.w  timer_divisor,d1
        lsl.l   #8,d1
        add.l   #256,d1
        cmp.l   d1,d0
        ble.s   flow_min_rate
        move.l  d1,d0
flow_min_rate:
        sub.l   #512,d1
        cmp.l   d1,d0
        bge.s   flow_set_rate
        move.l  d1,d0
flow_set_rate:
        move.w  d0,timer_period
        move.w  #$2400,sr
latch_complete:
        clr.w   pending_valid
        addq.l  #1,frames_shown
no_latch:
        subq.w  #1,ticks
        bne.s   no_commit
        move.w  frame_ticks,ticks
        tst.w   ready
        beq.s   no_commit
        move.l  queued,d0
        move.l  d0,pending
        move.l  queued_audio,pending_audio
        tst.w   audio_continuous
        beq.s   commit_dma
        move.l  pending_audio,audio_next
commit_dma:
        tst.w   audio_dma_active
        beq.s   commit_screen
        move.l  pending_audio,a0
        bsr     dma_set_next
        move.l  queued,d0
commit_screen:
        swap    d0
        move.b  d0,$ffff8201.w
        swap    d0
        lsr.w   #8,d0
        move.b  d0,$ffff8203.w
        move.w  #1,pending_valid
        clr.w   ready
no_commit:
        btst    #0,$fffffc00.w
        beq.s   no_key
        move.b  $fffffc02.w,d0
        cmp.b   #$36,d0
        bne.s   raw_escape
        move.w  #2,abort
        bra.s   no_key
raw_escape:
        cmp.b   #$01,d0
        bne.s   no_key
        move.w  #1,abort
no_key:
        movem.l (sp)+,d0-d7/a0
        rte
timer_a:
        move.l  a0,-(sp)
        move.l  audio_cursor,a0
        cmpa.l  audio_end,a0
        bhs.s   audio_ack
        move.l  (a0)+,$ffff8800.w
        move.l  (a0)+,$ffff8800.w
        move.l  (a0)+,$ffff8800.w
        move.l  a0,audio_cursor
        bra.s   audio_ack
; STV2 was fitted offline to change just one YM volume register per sample.
; This avoids the intermediate DAC levels of three consecutive volume writes.
timer_a_single:
        move.l  a0,-(sp)
        move.l  audio_cursor,a0
        cmpa.l  audio_end,a0
        bhs.s   audio_ack
        move.l  (a0)+,$ffff8800.w
        move.l  a0,audio_cursor
audio_ack:
        bclr    #5,$fffffa0f.w
        move.l  (sp)+,a0
        rte
; STV3 changes buffers at the sample boundary. The encoder guarantees that
; the next frame's initial state equals the previous frame's final state.
timer_a_flow:
        movem.l d0/a0,-(sp)
        move.l  audio_cursor,a0
        cmpa.l  audio_end,a0
        blo.s   flow_write
        bsr.s   count_flow
        move.l  audio_next,a0
        move.l  a0,d0
        beq.s   flow_ack
        clr.l   audio_next
        move.l  a0,audio_start
        moveq   #0,d0
        move.w  8188(a0),d0
        lsl.l   #2,d0
        add.l   a0,d0
        move.l  d0,audio_end
flow_write:
        move.l  (a0)+,$ffff8800.w
        move.l  a0,audio_cursor
        ; Fractional reload spreads tiny corrections across samples instead
        ; of alternating whole frames between visibly different pitches.
        move.w  timer_period,d0
        add.b   d0,timer_fraction
        bcc.s   flow_reload
        add.w   #256,d0
flow_reload:
        lsr.w   #8,d0
        move.b  d0,$fffffa1f.w
flow_ack:
        bclr    #5,$fffffa0f.w
        movem.l (sp)+,d0/a0
        rte
count_flow:
        tst.w   audio_continuous
        beq.s   count_flow_done
        tst.l   audio_start
        beq.s   count_flow_done
        move.l  audio_cursor,d0
        sub.l   audio_start,d0
        lsr.l   #2,d0
        add.l   d0,samples_played
        clr.l   audio_start
count_flow_done:
        rts
count_audio:
        tst.w   audio_continuous
        bne.s   count_audio_done
        tst.w   audio_dma_active
        bne.s   count_audio_done
        move.l  audio_end,d0
        sub.l   audio_cursor,d0
        divu    audio_stride,d0
        and.l   #$ffff,d0
        add.l   d0,empty_ticks
        move.l  audio_cursor,d0
        sub.l   audio_start,d0
        divu    audio_stride,d0
        and.l   #$ffff,d0
        add.l   d0,samples_played
count_audio_done:
        rts
; Cookie check is called through Supexec; never probe STE registers on STF.
detect_ste:
        moveq   #0,d0
        move.l  $5a0.w,a0
        move.l  a0,d1
        beq.s   detect_done
detect_cookie:
        move.l  (a0)+,d1
        beq.s   detect_done
        cmp.l   #$5f4d4348,d1
        beq.s   detect_machine
        addq.l  #4,a0
        bra.s   detect_cookie
detect_machine:
        move.l  (a0),d1
        swap    d1
        cmp.w   #1,d1
        bne.s   detect_done
        moveq   #1,d0
detect_done:
        rts
dma_save:
        lea     saved_dma,a0
        move.b  $ffff8901.w,(a0)+
        move.b  $ffff8903.w,(a0)+
        move.b  $ffff8905.w,(a0)+
        move.b  $ffff8907.w,(a0)+
        move.b  $ffff890f.w,(a0)+
        move.b  $ffff8911.w,(a0)+
        move.b  $ffff8913.w,(a0)+
        move.b  $ffff8921.w,(a0)+
        clr.b   $ffff8901.w
        move.b  #$81,$ffff8921.w
        rts
dma_restore:
        clr.b   $ffff8901.w
        lea     saved_dma,a0
        move.b  (a0)+,d0
        move.b  (a0)+,$ffff8903.w
        move.b  (a0)+,$ffff8905.w
        move.b  (a0)+,$ffff8907.w
        move.b  (a0)+,$ffff890f.w
        move.b  (a0)+,$ffff8911.w
        move.b  (a0)+,$ffff8913.w
        move.b  (a0)+,$ffff8921.w
        move.b  d0,$ffff8901.w
        rts
; Update loop reload pointers during the preceding half-frame. Do not stop
; the DAC at every VBL: the current buffer must finish without a silence gap.
dma_set_next:
        move.l  a0,d0
        move.l  d0,d1
        swap    d1
        move.b  d1,$ffff8903.w
        move.l  d0,d1
        lsr.w   #8,d1
        move.b  d1,$ffff8905.w
        move.b  d0,$ffff8907.w
        moveq   #0,d1
        move.w  8188(a0),d1
        add.l   d1,d0
        move.l  d0,d1
        swap    d1
        move.b  d1,$ffff890f.w
        move.l  d0,d1
        lsr.w   #8,d1
        move.b  d1,$ffff8911.w
        move.b  d0,$ffff8913.w
        rts
